async fn relay_bidirectional<AR, AW, BR, BW>(
	mut a_read: AR,
	mut a_write: AW,
	mut b_read: BR,
	mut b_write: BW,
) -> std::io::Result<()>
where
	AR: AsyncRead + Unpin,
	AW: AsyncWrite + Unpin,
	BR: AsyncRead + Unpin,
	BW: AsyncWrite + Unpin,
{
	let a_to_b = tokio::io::copy(&mut a_read, &mut b_write);
	let b_to_a = tokio::io::copy(&mut b_read, &mut a_write);
	tokio::pin!(a_to_b, b_to_a);

	tokio::select! {
		r = &mut a_to_b => { r?; }
		r = &mut b_to_a => { r?; }
	}

	Ok(())
}

